foundation.question_text:
Solve $(x-1)(x-5)<0$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.65]
\draw[->] (-1.5,0) -- (7.0,0) node[right] {$x$};
\draw[->] (0,-5.2) -- (0,6.5) node[above] {$y$};
\foreach \x in {-1,1,2,3,4,5,6} {\draw (\x,0.15) -- (\x,-0.15) node[below, font=\scriptsize] {$\x$};
}
\foreach \y in {-4,-2,2,4,6} {\draw (0.15,\y) -- (-0.15,\y) node[left, font=\scriptsize] {$\y$};
}
\node[below left, font=\scriptsize] at (0,0) {$0$};
\draw[thick, <->, domain=-0.1:6.1, samples=60, smooth, variable=\x] plot ({\x}, {(\x-1)*(\x-5)});
\fill (1,0) circle (2.5pt);
\fill (5,0) circle (2.5pt);
\node[above] at (3, 1.5) {$y = (x-1)(x-5)$};
\end{tikzpicture}
[/tikz]

development.question_text:
Solve $-x^{2}+x+12>0$.
[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, scale=0.5]
\draw[->] (-4.5,0) -- (5.5,0) node[right] {$x$};
\draw[->] (0,-4.8) -- (0,14.5) node[above] {$y$};
\foreach \x in {-4,-3,-2,-1,1,2,3,4,5} {\draw (\x,0.15) -- (\x,-0.15) node[below, font=\scriptsize] {$\x$};
}
\foreach \y in {-4,-2,2,4,6,8,10,12,14} {\draw (0.15,\y) -- (-0.15,\y) node[left, font=\scriptsize] {$\y$};
}
\node[below left, font=\scriptsize] at (0,0) {$0$};
\draw[thick, <->, domain=-3.5:4.5, samples=60, smooth, variable=\x] plot ({\x}, {(4-\x)*(\x+3)});
\fill (-3,0) circle (2.5pt);
\fill (4,0) circle (2.5pt);
\node[above right] at (2.0, 11.5) {$y = -x^{2}+x+12$};
\end{tikzpicture}
[/tikz]
